"""Retiming search for layouts already generated by L2.

Each input row defines a fixed per-qubit order class.  ``generic_exact`` builds
the complete closed-form objective for that class and CP-SAT optimizes all legal
layer assignments at the requested depth.  No new layout enumeration occurs in
this file.
"""
from __future__ import annotations
import argparse
import ast
import json
import sys
from pathlib import Path

from ortools.sat.python import cp_model

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path[:0] = [str(HERE), str(ROOT / "lanes" / "me_layout"), str(ROOT / "lanes" / "L2_layout_cpsat")]
import l2model  # noqa: E402
from generic_exact import ExactObjective, LayoutSchedule, load_row  # noqa: E402


INPUTS = {
    "A1+none": ROOT / "lanes" / "L2_layout_cpsat" / "res_A1+none_9s_2000.json",
    "A1+e42": ROOT / "lanes" / "L2_layout_cpsat" / "res_A1+e42_9_11.json",
    "A1+m42": ROOT / "lanes" / "L2_layout_cpsat" / "res_A1+m42_10s_1000.json",
    "A2+none": ROOT / "lanes" / "L2_layout_cpsat" / "res_A2+none_9s_2300.json",
    "v6+none": ROOT / "lanes" / "L2_layout_cpsat" / "res_v6+none_9s_2100.json",
}


def key_json(k):
    return [str(x) for x in k]


def run_one(name, path, idx, seconds):
    row = json.load(open(path))[idx]
    model = l2model.variant(name)
    assign, orient = load_row(path, idx)
    if not model.feasible(assign, orient):
        return {"name": name, "source": f"{path}#{idx}", "status": "invalid_input"}
    initial = ExactObjective(model, assign, orient)
    schedule = LayoutSchedule(model, 10 if len(assign) > 31 else 9, fixed_order=(assign, orient))
    mech, pairs = initial.install(schedule)
    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = seconds
    solver.parameters.num_search_workers = 8
    solver.parameters.random_seed = 0
    solver.parameters.cp_model_presolve = False
    status = solver.solve(schedule.model)
    out = {
        "name": name,
        "source": f"{path}#{idx}",
        "input_proxy": row[0],
        "input_exact": initial.value(assign),
        "status": solver.status_name(status),
        "objective_rounded": solver.objective_value / (2 * 10**18) if status in (cp_model.OPTIMAL, cp_model.FEASIBLE) else None,
        "bound_rounded": solver.best_objective_bound / (2 * 10**18) if status in (cp_model.OPTIMAL, cp_model.FEASIBLE) else None,
        "mechanisms": mech,
        "pairs": pairs,
        "rounding_bound": initial.rounding_bound,
        "scope": "fixed orientation and fixed per-qubit CNOT order; all legal layer assignments in the stated LMAX",
    }
    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        aa, oo = schedule.extract(solver)
        out["proxy"] = initial.value(aa)
        out["gmodel_feasible"] = bool(model.feasible(aa, oo))
        out["assign"] = [[key_json(k), int(aa[k])] for k in model.keys]
        out["orientation"] = oo
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--seconds", type=float, default=60)
    ap.add_argument("--per-file", type=int, default=3)
    ap.add_argument("--tag", default="generic_search")
    args = ap.parse_args()
    rows = []
    seen = set()
    for name, path in INPUTS.items():
        if not path.exists():
            continue
        raw = json.load(open(path))
        for idx in range(min(args.per_file, len(raw))):
            a, o = load_row(path, idx)
            model = l2model.variant(name)
            # Preserve distinct order classes; equal proxy rows often duplicate.
            per = {}
            for k in model.keys:
                for q in model.qubits_of(k, o):
                    per.setdefault(q, []).append(k)
            cls = (name, tuple(o), tuple((q, tuple(sorted(ks, key=a.__getitem__))) for q, ks in sorted(per.items())))
            if cls in seen:
                continue
            seen.add(cls)
            print("solve", name, idx, "input", raw[idx][0], "class", len(seen), flush=True)
            result = run_one(name, path, idx, args.seconds)
            rows.append(result)
            print(result, flush=True)
            json.dump(rows, open(HERE / f"{args.tag}.json", "w"), indent=2)
    rows.sort(key=lambda r: r.get("proxy", float("inf")))
    json.dump(rows, open(HERE / f"{args.tag}.json", "w"), indent=2)
    print(json.dumps({"classes": len(rows), "best": rows[0].get("proxy") if rows else None}), flush=True)


if __name__ == "__main__":
    main()
